package com.fooddelivery.order; import io.github.resilience4j.circuitbreaker.annotation.CircuitBreaker; import org.springframework.stereotype.Service; import org.springframework.web.reactive.function.client.WebClient; import java.math.BigDecimal; @Service public class RestaurantClient{final WebClient.Builder builder; RestaurantClient(WebClient.Builder b){builder=b;} record MenuItem(Long id,String name,String description,BigDecimal price,String imageUrl,boolean available,Long restaurantId){} @CircuitBreaker(name="restaurantClient",fallbackMethod="fallback") public MenuItem getItem(Long id){return builder.baseUrl("http://RESTAURANT-SERVICE").build().get().uri("/menu-items/{id}",id).retrieve().bodyToMono(MenuItem.class).block();} MenuItem fallback(Long id,Throwable t){throw new IllegalStateException("Restaurant service is temporarily unavailable",t);}}